// Prior works are reassessed below; old raw attainments remain separate from
// curved contributions. Each explicit note states the fresh reason for retention.
function prior(i,reason,eligibility,notes,extra={}){
 const b=byIndex.get(i),p=b.prior;
 const a=score(i,p.year,p.periodEnd,p.raw.slice(),notes,reason,eligibility,[],{
  status:p.status,confidence:p.confidence||'moderate',T11:p.T11,T12:p.T12,yearConfidence:p.yearConfidence||'moderate',periodConfidence:p.periodConfidence||'moderate',
  amazon:structuredClone(p.amazon),reader:p.reader||'Unavailable',purchaseUrl:p.purchaseUrl,purchaseFormat:'Retained identified edition locator; format is recorded in the existing edition evidence.',
  enrichment:structuredClone(b.priorEnrichment||{}),...extra});
 if(a.amazon.count==null)a.amazon.status='Retain the previously audited unknown-count fallback after the cited retrieval attempts; no new count is inferred from popularity.';
 if(p.status==='vetoed'){a.veto=p.veto;a.vetoConfidence=p.vetoConfidence||'moderate';}
 Object.assign(a,extra);
 a.reassessment=extra.reassessment||'Read the cited prior book assessment and current deduction record, then compared the new source mentions. Both hard exclusions, all five vetoes, all ten raw attainments and both thematic flags were reconsidered. The ten reasons below support retention; a repeated mention is not quality evidence. Original year, topic endpoint and the dated Amazon observation/fallback remain unchanged unless a correction is stated below. The calculated verdict is recomputed from unrounded values.';
 return a;
}
